import { NextRequest, NextResponse } from 'next/server';
import { auth } from '@/auth';
import { s3Client } from '@/lib/s3';
import { GetObjectCommand } from '@aws-sdk/client-s3';

export async function GET(req: NextRequest) {
  const session = await auth();
  if (!session?.user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const exportId = req.nextUrl.searchParams.get('exportId');
  if (!exportId) {
    return NextResponse.json({ error: 'exportId required' }, { status: 400 });
  }

  const command = new GetObjectCommand({
    Bucket: process.env.COMPLIANCE_ARCHIVES_BUCKET,
    Key: `exports/${exportId}.tar.gz`
  });
  const s3Response = await s3Client.send(command);

  return new NextResponse(s3Response.Body as any, {
    headers: {
      'Content-Type': 'application/gzip',
      'Content-Disposition': `attachment; filename="audit-${exportId}.tar.gz"`
    }
  });
}

